import {metrics,focusMap,requirement,farFieldKm,wavelength} from './physics.js';
let cfg={nodes:16,formation:'Grid',baselineM:500,rangeKm:550,freqGHz:20,totalPowerW:320,powerMode:'Total fixed',pathErrorMm:0,rfPhaseRmsDeg:0,freqOffsetHz:0,command:'Estimated',seed:426,mapSpanKm:10,lossTargetDb:1,timeS:0},tab='formation',last=null;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], fmt=(x,d=2)=>Number.isFinite(x)?x.toFixed(d):'—';
const field=(k,l,a,b,s,u='')=>`<div class="field"><label><span>${l}</span><span>${u}</span></label><input data-key="${k}" type="number" min="${a}" max="${b}" step="${s}" value="${cfg[k]}"></div>`;
const select=(k,l,o)=>`<div class="field"><label>${l}</label><select data-key="${k}">${o.map(x=>`<option ${cfg[k]===x?'selected':''}>${x}</option>`).join('')}</select></div>`;
function controls(){let h=`<div class="group"><h3>Formation</h3>${field('nodes','위성 수',1,64,1)}${select('formation','배치',['Grid','Ring','Line','Random'])}${field('baselineM','최대 기준선',1,5000,1,'m')}${field('rangeKm','목표 거리',100,50000,1,'km')}</div><div class="group"><h3>RF</h3>${field('freqGHz','주파수',.1,100,.1,'GHz')}<div class="quick"><button data-freq="2">2 GHz</button><button data-freq="20">20 GHz</button><button data-freq="30">30 GHz</button></div>${field('totalPowerW',cfg.powerMode==='Per node'?'노드당 RF 전력':'총 RF 전력',.1,100000,1,'W')}${select('powerMode','전력 기준',['Total fixed','Per node'])}${select('command','위상 보정',['Estimated','Oracle','None'])}</div>`;
 if(tab==='focus')h+=`<div class="group"><h3>Focus map</h3>${field('mapSpanKm','지도 폭',.2,100,.2,'km')}</div>`;
 if(tab==='sync')h+=`<div class="group"><h3>Residual errors</h3>${field('pathErrorMm','경로 추정오차 RMS',0,1000,.1,'mm')}${field('rfPhaseRmsDeg','추가 RF 위상 RMS',0,180,.1,'deg')}${field('freqOffsetHz','노드별 주파수편차 RMS',0,10000,.01,'Hz')}${field('timeS','경과 시간',0,100,.001,'s')}</div>`;
 if(tab==='req')h+=`<div class="group"><h3>Requirement</h3>${field('lossTargetDb','평균 결맞음 손실 목표',.01,12,.01,'dB')}</div>`;
 $('#controls').innerHTML=h;$$('#controls [data-key]').forEach(el=>el.onchange=()=>{let k=el.dataset.key;cfg[k]=el.tagName==='SELECT'?el.value:Number(el.value);run()});$$('[data-freq]').forEach(b=>b.onclick=()=>{cfg.freqGHz=Number(b.dataset.freq);render()})}
function results(m){let r=requirement(cfg.nodes,cfg.lossTargetDb,cfg.freqGHz),ff=farFieldKm(cfg.baselineM,cfg.freqGHz);$('#results').innerHTML=`<div class="card"><div class="k">결맞음 손실</div><div class="v">${fmt(m.coherenceLossDb)} dB</div><div class="s">동일 순간 이상적 위상정렬 대비</div></div><div class="card"><div class="k">비결맞음 기준 대비</div><div class="v">${fmt(m.gainVsIncoherentDb)} dB</div><div class="s">같은 활성 노드·같은 전력</div></div><div class="card"><div class="k">결맞음 계수</div><div class="v">${fmt(100*m.coherence,1)}%</div><div class="s">Pactual / Pideal</div></div><div class="card"><div class="k">파장</div><div class="v">${fmt(wavelength(cfg.freqGHz)*1000,3)} mm</div><div class="s">${cfg.freqGHz} GHz</div></div><div class="card"><div class="k">원거리장 판단 척도</div><div class="v">${ff>10000?fmt(ff/1000,1)+'k':fmt(ff,0)} km</div><div class="s">2B²/λ · 엄밀 경계가 아닌 척도</div></div>${r?`<div class="card"><div class="k">${cfg.lossTargetDb} dB 평균손실 조건</div><div class="v">${fmt(r.pathRmsMm,3)} mm</div><div class="s">등가 잔여 경로 RMS · ${fmt(r.phaseRmsDeg,2)}°</div></div>`:''}<div class="warn ${m.coherenceLossDb<1?'ok':''}">${cfg.command==='Oracle'?'Oracle은 참값을 이용한 이상적 상한 비교군입니다.':'Estimated는 추정 위치로 위상명령을 생성합니다.'} 경로 RMS는 3D 위치유지 RMS와 동일하지 않습니다.</div>`}
function canvas(w=820,h=560){let c=document.createElement('canvas');c.width=w;c.height=h;$('#visual').innerHTML='';$('#visual').appendChild(c);return[c,c.getContext('2d')]}
function formationView(m){let[c,x]=canvas(),s=420/Math.max(cfg.baselineM,1);x.translate(c.width/2,c.height/2);x.strokeStyle='#183d55';for(let i=-4;i<=4;i++){x.beginPath();x.moveTo(-380,i*50);x.lineTo(380,i*50);x.stroke();x.beginPath();x.moveTo(i*50,-230);x.lineTo(i*50,230);x.stroke()}for(let i=0;i<m.truth.length;i++){let p=m.truth[i],e=m.estimate[i];x.strokeStyle='#f94239';x.beginPath();x.moveTo(p[0]*s,p[1]*s);x.lineTo(e[0]*s,e[1]*s);x.stroke();x.fillStyle='#eaf3f8';x.beginPath();x.arc(p[0]*s,p[1]*s,5,0,Math.PI*2);x.fill();x.fillStyle='#f94239';x.beginPath();x.arc(e[0]*s,e[1]*s,2.5,0,Math.PI*2);x.fill()}x.fillStyle='#7895a9';x.font='12px sans-serif';x.fillText(`${cfg.baselineM} m baseline · icons not to scale`,-380,255);$('#visual').insertAdjacentHTML('beforeend','<div class="legend">흰색: truth · 빨강: estimate<br>목표방향에 수직인 편대 평면</div>')}
function focusView(){let fm=focusMap(cfg,71,cfg.timeS),[c,x]=canvas(720,600),img=x.createImageData(fm.size,fm.size);for(let k=0;k<fm.values.length;k++){let db=10*Math.log10(Math.max(fm.values[k]/fm.max,1e-6)),t=Math.max(0,Math.min(1,(db+35)/35));img.data[4*k]=Math.round(249*t);img.data[4*k+1]=Math.round(66+120*t);img.data[4*k+2]=Math.round(57+80*(1-t));img.data[4*k+3]=255}let off=document.createElement('canvas');off.width=fm.size;off.height=fm.size;off.getContext('2d').putImageData(img,0,0);x.imageSmoothingEnabled=false;x.drawImage(off,60,30,540,540);x.fillStyle='#fff';x.fillRect(329,299,3,3);x.fillStyle='#9db4c2';x.font='12px sans-serif';x.fillText(`±${cfg.mapSpanKm/2} km · map maximum normalized`,60,590);$('#visual').insertAdjacentHTML('beforeend','<div class="legend">흰 점: 목표점<br>색상: 탐색범위 내 상대전력<br>격자보다 좁은 부엽은 놓칠 수 있음</div>')}
function syncView(m){let[c,x]=canvas(),cx=c.width/2,cy=270,R=170;x.strokeStyle='#27465b';x.beginPath();x.arc(cx,cy,R,0,Math.PI*2);x.stroke();x.beginPath();x.moveTo(cx-R-30,cy);x.lineTo(cx+R+30,cy);x.moveTo(cx,cy-R-30);x.lineTo(cx,cy+R+30);x.stroke();m.phases.forEach((a,i)=>{let ang=((a%(2*Math.PI))+2*Math.PI)%(2*Math.PI),ex=cx+R*Math.cos(ang),ey=cy-R*Math.sin(ang);x.strokeStyle=`hsl(${190+i*130/m.phases.length} 70% 65%)`;x.beginPath();x.moveTo(cx,cy);x.lineTo(ex,ey);x.stroke();x.fillStyle='#dbeaf2';x.font='10px sans-serif';x.fillText(String(i+1),ex,ey)});x.fillStyle='#8ca8b8';x.font='12px sans-serif';x.fillText('각 화살표 = 목표점에서의 노드별 상대 반송파 위상',30,535)}
function reqView(){let r=requirement(cfg.nodes,cfg.lossTargetDb,cfg.freqGHz);$('#visual').innerHTML=r?`<div class="reqbox"><div class="small">독립·평균 0 가우시안 노드별 잔여위상, 동일 채널 진폭 가정</div><h2>평균 결맞음 손실 ${cfg.lossTargetDb} dB</h2><div class="reqgrid"><div class="card"><div class="k">위상 RMS</div><div class="v">${fmt(r.phaseRmsDeg,3)}°</div></div><div class="card"><div class="k">등가 경로 RMS</div><div class="v">${fmt(r.pathRmsMm,4)} mm</div></div><div class="card"><div class="k">등가 시간 RMS</div><div class="v">${fmt(r.timeRmsPs,4)} ps</div></div></div><div class="warn">이 값은 평균 전력 손실의 해석식입니다. 95% 실험 성공조건이나 절대 UTC 동기 요구조건이 아닙니다.</div><div class="small" style="margin-top:20px">E[C] = 1/N + (1 - 1/N) exp(-σ²)<br>ΔR = σλ / 2π</div></div>`:`<div class="reqbox">현재 조건에서는 해석식 역산이 정의되지 않습니다.</div>`}
const info={formation:['편대 배치','명목·실제·추정 위치를 분리해 배열 형상을 확인합니다.'],focus:['빔·초점','구면파로 목표 주변의 희소배열 간섭무늬를 계산합니다.'],sync:['동기오차','목표점에서 노드별 반송파 위상 벡터가 어떻게 합쳐지는지 봅니다.'],req:['요구조건·비교','목표 평균 결맞음 손실에서 허용 잔여오차를 역산합니다.']};
function run(){cfg.nodes=Math.max(1,Math.min(64,Math.round(cfg.nodes)));last=metrics(cfg,cfg.timeS);render()}
function render(){controls();$('#title').textContent=info[tab][0];$('#subtitle').textContent=info[tab][1];last=metrics(cfg,cfg.timeS);results(last);if(tab==='formation')formationView(last);else if(tab==='focus')focusView();else if(tab==='sync')syncView(last);else reqView()}
$$('.tab').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;$$('.tab').forEach(x=>x.classList.toggle('active',x===b));render()});$('#run').onclick=run;
function download(name,text,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#saveJson').onclick=()=>download('virtual-satellite-scenario.json',JSON.stringify({schema:'virtual-satellite-v0.1',...cfg},null,2),'application/json');
$('#saveCsv').onclick=()=>{let m=metrics(cfg,cfg.timeS),rows=[['metric','value','unit'],['nodes',cfg.nodes,'count'],['frequency',cfg.freqGHz,'GHz'],['baseline',cfg.baselineM,'m'],['path_error_rms',cfg.pathErrorMm,'mm'],['rf_phase_rms',cfg.rfPhaseRmsDeg,'deg'],['coherence',m.coherence,'ratio'],['coherence_loss',m.coherenceLossDb,'dB'],['gain_vs_incoherent',m.gainVsIncoherentDb,'dB']];download('virtual-satellite-result.csv','\ufeff'+rows.map(r=>r.join(',')).join('\n'),'text/csv')};
$('#loadJson').onchange=async e=>{try{let o=JSON.parse(await e.target.files[0].text());for(const k of Object.keys(cfg))if(k in o)cfg[k]=o[k];render()}catch{alert('유효한 시나리오 JSON을 읽지 못했습니다.')}};run();
